import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.autotune(
    configs=[
        triton.Config({"BLOCK_N": 32}, num_warps=4),
    ],
    key=["N"],
)
@triton.jit
def reverse_cumsum_kernel(
    x_ptr,
    out_ptr,
    M,
    N: tl.constexpr,
    stride_xm,
    stride_xn,
    stride_om,
    stride_on,
    BLOCK_N: tl.constexpr,
):
    row = tl.program_id(0)
    x_base = x_ptr + row.to(tl.int64) * stride_xm
    out_base = out_ptr + row.to(tl.int64) * stride_om

    # Pass 1: compute total sum of the row
    total = 0.0
    for col_start in range(0, N, BLOCK_N):
        cols = col_start + tl.arange(0, BLOCK_N)
        mask = cols < N
        x = tl.load(x_base + cols * stride_xn, mask=mask, other=0.0).to(tl.float32)
        total = total + tl.sum(x, axis=0)

    # Pass 2: compute suffix sums (left-to-right)
    # suffix[i] = total - exclusive_prefix_sum[i]
    # where exclusive_prefix[i] = running_prefix + cumsum_inc[local_i] - x[local_i]
    running_prefix = 0.0
    for col_start in range(0, N, BLOCK_N):
        cols = col_start + tl.arange(0, BLOCK_N)
        mask = cols < N
        x = tl.load(x_base + cols * stride_xn, mask=mask, other=0.0).to(tl.float32)
        cumsum_inc = tl.cumsum(x, axis=0)
        suffix = total - running_prefix - cumsum_inc + x
        tl.store(out_base + cols * stride_on, suffix, mask=mask)
        running_prefix = running_prefix + tl.sum(x, axis=0)


class Model(nn.Module):
    def __init__(self, dim):
        super(Model, self).__init__()
        self.dim = dim

    def forward(self, x):
        x = x.contiguous()
        M, N = x.shape
        output = torch.empty_like(x)

        grid = (M,)
        reverse_cumsum_kernel[grid](
            x,
            output,
            M,
            N,
            x.stride(0),
            x.stride(1),
            output.stride(0),
            output.stride(1),
        )
        return output


